play:flex;align-items:center;gap:6px;min-width:0}\n.back{flex:none;height:26px;padding:0 10px;border:1px solid var(--line);border-radius:13px;background:transparent;color:var(--ink);white-space:nowrap}\n.ttl{min-width:0;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n\n.detail,.form{flex:1 1 auto;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.body{flex:1 1 auto;display:block;overflow:auto}\n.fld{margin-bottom:7px}\n.fl{color:var(--muted);font-size:10px;margin-bottom:1px}\n.fv{white-space:pre-wrap;overflow-wrap:anywhere}\n.acts-row{flex:none;display:flex;gap:6px;min-width:0}\n.acts-row .btn{flex:1 1 0;height:30px;padding:0 4px}\n\n.fbody{flex:1 1 auto;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:6px}\n.fbody label{flex:1 0 auto;display:flex;flex-direction:column;gap:2px;color:var(--muted);font-size:10px}\n.inp{flex:1 1 auto;width:100%;min-height:44px;resize:none;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font-size:13px;line-height:1.4}\n.inp:focus{outline:2px solid var(--accent);outline-offset:0}\n.err,.ok{flex:none;font-size:11px;overflow-wrap:anywhere}\n.ok{color:var(--muted)}\n\n/* 6x3 \u6a2a\u5411\uff1a\u5de6\u9898\u5361\uff0c\u53f3\u4fa7\u7eb5\u5411\u8bc4\u5206 */\n.card[data-size=\"6x3\"] .study{flex-direction:row}\n.card[data-size=\"6x3\"] .face{flex:1 1 0}\n.card[data-size=\"6x3\"] .rates{flex:0 0 128px;flex-direction:column}\n.card[data-size=\"6x3\"] .rate{flex:1 1 0;min-height:0;flex-direction:row;justify-content:space-between;padding:0 10px}\n.card[data-size=\"6x3\"] .rates.one{justify-content:center}\n.card[data-size=\"6x3\"] .rates.one .btn{flex:0 0 auto;height:44px}\n.card[data-size=\"6x3\"] .row,.card[data-size=\"6x6\"] .row{flex-direction:row;align-items:center;justify-content:space-between;gap:8px}\n.card[data-size=\"6x3\"] .rq{flex:1 1 auto;width:auto;-webkit-line-clamp:1}\n.card[data-size=\"6x6\"] .rq{flex:1 1 auto;width:auto}\n.card[data-size=\"6x3\"] .rt,.card[data-size=\"6x6\"] .rt{flex:none;font-size:11px}\n.card[data-size=\"6x3\"] .fbody{flex-flow:row wrap;align-content:stretch}\n.card[data-size=\"6x3\"] .fbody label{flex:1 1 45%;min-width:0}\n.card[data-size=\"6x3\"] .err,.card[data-size=\"6x3\"] .ok{flex:0 0 100%}\n\n/* \u7ad6\u5411\u4e0e\u5927\u5361\uff1a\u66f4\u5927\u7684\u5b57\u53f7\u4e0e\u7559\u767d */\n.card[data-size=\"3x6\"] .qtext{font-size:17px}\n.card[data-size=\"3x6\"] .atext{font-size:15px}\n.card[data-size=\"3x6\"] .rate{min-height:46px}\n.card[data-size=\"6x6\"] .fc{padding:14px;gap:10px;font-size:13px}\n.card[data-size=\"6x6\"] .face{padding:16px 18px;border-radius:16px}\n.card[data-size=\"6x6\"] .qtext{font-size:24px}\n.card[data-size=\"6x6\"] .atext{font-size:20px}\n.card[data-size=\"6x6\"] .qs{font-size:13px;-webkit-line-clamp:3}\n.card[data-size=\"6x6\"] .tag{font-size:11px;margin-bottom:6px}\n.card[data-size=\"6x6\"] .rate{min-height:56px}\n.card[data-size=\"6x6\"] .rl{font-size:15px}\n.card[data-size=\"6x6\"] .ri{font-size:12px}\n.card[data-size=\"6x6\"] .btn{height:44px}\n.card[data-size=\"6x6\"] .tab{height:30px}\n.card[data-size=\"6x6\"] .inp{font-size:15px;min-height:80px}\n.card[data-size=\"6x6\"] .acts-row .btn{height:40px}\n.card[data-size=\"6x6\"] .row{padding:9px 12px}\n";
// 知识点记忆卡：题目 -> 翻答案 -> 记住了/勉强记得/忘了 -> 自动排下次复习日期
function parseD(s){var p=String(s).split('-').map(Number);return new Date(p[0],p[1]-1,p[2]);}
function fmtD(d){var m=d.getMonth()+1,x=d.getDate();return d.getFullYear()+'-'+(m<10?'0':'')+m+'-'+(x<10?'0':'')+x;}
function addDays(s,n){var d=parseD(s);d.setDate(d.getDate()+n);return fmtD(d);}
function diffDays(a,b){return Math.round((parseD(b)-parseD(a))/86400000);}
// 复习间隔（天）：忘了=明天重来；勉强记得=略增；记住了=约 2.5 倍
function nextIvl(c,r){
  var i=c.ivl||0;
  if(r==='good')return Math.min(365,Math.max(3,Math.round(i*2.5)));
  if(r==='hard')return Math.min(365,Math.max(2,Math.round(i*1.2)));
  return 1;
}
var RATES=[{k:'good',name:'记住了',icon:'✓'},{k:'hard',name:'勉强记得',icon:'△'},{k:'again',name:'忘了',icon:'✕'}];
function ivlText(n){return n===1?'明天':n+'天后';}
function dueLabel(due,t){var d=diffDays(t,due);if(d<0)return '逾期'+(-d)+'天';if(d===0)return '今天';if(d===1)return '明天';return d+'天后';}
function resText(r){return r==='good'?'记住了':r==='hard'?'勉强记得':r==='again'?'忘了':'';}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day}=ctx;
  const h=(t,a,...k)=>el(t,a||{},...k.filter(x=>x!==null&&x!==undefined&&x!==false));
  const cards=(state&&Array.isArray(state.cards)?state.cards:[]).filter(c=>c&&c.id);
  const t=day();
  const dueOf=c=>c.due||t;
  const byDue=(a,b)=>dueOf(a)<dueOf(b)?-1:dueOf(a)>dueOf(b)?1:0;
  const dueList=cards.filter(c=>dueOf(c)<=t).sort(byDue);
  const doneToday=cards.filter(c=>c.last===t).length;
  const view=ui.view||'study';
  const go=p=>{Object.assign(ui,p);redraw();};
  const listOf=s=>(s&&Array.isArray(s.cards)?s.cards:[]);
  const nextUiOf=p=>Object.assign({},ui,p);

  function openForm(c){
    go({view:'form',draft:c?{id:c.id,q:c.q,a:c.a}:{q:'',a:''},err:'',msg:'',saving:false,added:0,
      back:view==='form'?(ui.back||'study'):view});
  }
  function closeForm(){
    const b=ui.back||'study';
    go({view:b,draft:null,err:'',msg:'',saving:false,flipped:false});
  }

  function rate(c,r){
    if(ui.rating)return;
    ui.rating=true;
    const today=day(),ni=nextIvl(c,r),id=c.id;
    commit(s=>Object.assign({},s,{cards:listOf(s).map(x=>x.id!==id?x:Object.assign({},x,{
      ivl:ni,due:addDays(today,ni),n:(x.n||0)+1,last:today,res:r,lapse:(x.lapse||0)+(r==='again'?1:0)
    }))}),nextUiOf({rating:false,flipped:false,aheadId:null,view:'study'}))
      .then(ok=>{if(ok===false)ui.rating=false;})
      .catch(()=>{ui.rating=false;redraw();});
  }

  function save(again){
    const d=ui.draft||{q:'',a:''};
    const q=String(d.q||'').trim(),a=String(d.a||'').trim();
    if(!q||!a){ui.err=!q?'请先写问题':'请先写答案';redraw();return;}
    if(ui.saving)return;
    ui.saving=true;
    const editing=!!d.id,id=d.id||uid(),back=ui.back||'study',today=day();
    const fail=()=>{ui.saving=false;redraw();};
    if(editing){
      commit(s=>Object.assign({},s,{cards:listOf(s).map(x=>x.id===id?Object.assign({},x,{q:q,a:a}):x)}),
        nextUiOf({view:'detail',sel:id,draft:null,err:'',saving:false}))
        .then(ok=>{if(ok===false)ui.saving=false;}).catch(fail);
    }else{
      const nu=again
        ?nextUiOf({view:'form',draft:{q:'',a:''},err:'',saving:false,added:(ui.added||0)+1,msg:'已添加 '+((ui.added||0)+1)+' 张，可继续输入'})
        :nextUiOf({view:back==='detail'?'list':back,draft:null,err:'',msg:'',saving:false,flipped:false});
      commit(s=>Object.assign({},s,{cards:listOf(s).concat([{id:id,q:q,a:a,created:today,due:today,ivl:0,n:0}])}),nu)
        .then(ok=>{if(ok===false)ui.saving=false;}).catch(fail);
    }
  }

  function removeCard(id){
    if(ui.saving)return;
    ui.saving=true;
    commit(s=>Object.assign({},s,{cards:listOf(s).filter(x=>x.id!==id)}),
      nextUiOf({view:'list',sel:null,confirmDel:false,saving:false}))
      .then(ok=>{if(ok===false)ui.saving=false;})
      .catch(()=>{ui.saving=false;redraw();});
  }


  const btn=(label,cls,fn,extra)=>h('button',Object.assign({type:'button',class:'btn '+(cls||''),onclick:fn},extra||{}),label);
  const emptyBox=(title,text,...acts)=>h('div',{class:'empty'},
    h('div',{class:'et'},title),h('div',{class:'ex'},text),...acts);

  function nav(){
    const inList=view==='list'||view==='detail';
    const tab=(label,on,fn,cls)=>h('button',{type:'button',class:'tab'+(on?' on':'')+(cls?' '+cls:''),onclick:fn},label);
    return h('div',{class:'nav'},
      tab('复习'+(dueList.length?' '+dueList.length:''),view==='study',()=>go({view:'study',flipped:false,aheadId:null})),
      tab('全部 '+cards.length,inList,()=>go({view:'list'})),
      h('button',{type:'button',class:'tab add','aria-label':'新增卡片',onclick:()=>openForm(null)},'＋'),
      h('span',{class:'meta'},'今天待复习 '+dueList.length+' · 已复习 '+doneToday)
    );
  }

  function studyView(){
    if(!cards.length){
      return emptyBox('还没有卡片','点「＋」写下第一个问题和答案，卡片会保存在这里。',
        btn('添加第一张','primary',()=>openForm(null)));
    }
    const ahead=ui.aheadId?cards.find(c=>c.id===ui.aheadId):null;
    const cur=ahead||dueList[0];
    if(!cur){
      const nxt=cards.slice().sort(byDue)[0];
      return emptyBox('今天的复习完成了','已复习 '+doneToday+' 张。下一张：'+dueLabel(dueOf(nxt),t)+'（'+dueOf(nxt).slice(5)+'）',
        btn('提前复习下一张','primary',()=>go({aheadId:nxt.id,flipped:false})));
    }
    const flipped=!!ui.flipped;
    const face=h('div',{class:'face'+(flipped?' flipped':''),role:'button',tabindex:'0',
      'aria-label':flipped?'返回题目':'翻看答案',onclick:()=>go({flipped:!flipped})},
      h('div',{class:'scroll'},
        h('div',{class:'tag'},(flipped?'答案':'题目')+(ahead?' · 提前复习':'')),
        h('div',{class:'mid'},
          flipped&&h('div',{class:'qs'},cur.q),
          h('div',{class:flipped?'atext':'qtext'},flipped?cur.a:cur.q))));
    const acts=flipped
      ?h('div',{class:'rates'},...RATES.map(r=>h('button',{type:'button',class:'rate '+r.k,disabled:!!ui.rating,
          onclick:()=>rate(cur,r.k)},
          h('span',{class:'rl'},r.icon+' '+r.name),h('span',{class:'ri'},ivlText(nextIvl(cur,r.k))))))
      :h('div',{class:'rates one'},btn('翻看答案','primary flip',()=>go({flipped:true})));
    return h('div',{class:'study'},face,acts);
  }

  function listView(){
    if(!cards.length){
      return emptyBox('还没有卡片','点「＋」添加第一张。',btn('添加卡片','primary',()=>openForm(null)));
    }
    const sorted=cards.slice().sort(byDue);
    return h('div',{class:'list'},...sorted.map(c=>h('button',{type:'button',class:'row',
      onclick:()=>go({view:'detail',sel:c.id,confirmDel:false})},
      h('span',{class:'rq'},c.q),
      h('span',{class:'rt'+(dueOf(c)<=t?' due':'')},dueLabel(dueOf(c),t)))));
  }


  const bar=(title,fn)=>h('div',{class:'bar'},
    h('button',{type:'button',class:'back','aria-label':'返回',onclick:fn},'‹ 返回'),
    h('span',{class:'ttl'},title));
  const fld=(label,value)=>h('div',{class:'fld'},h('div',{class:'fl'},label),h('div',{class:'fv'},value));

  function detailView(){
    const c=cards.find(x=>x.id===ui.sel);
    if(!c)return listView();
    const rec=(c.n?c.n+' 次':'尚未复习')+(c.last?' · 上次 '+c.last+' '+resText(c.res):'')+(c.lapse?' · 忘记 '+c.lapse+' 次':'');
    const actions=ui.confirmDel
      ?h('div',{class:'acts-row'},
          btn('取消','',()=>go({confirmDel:false})),
          btn('确认删除','primary',()=>removeCard(c.id),{disabled:!!ui.saving}))
      :h('div',{class:'acts-row'},
          btn('编辑','',()=>openForm(c)),
          btn('删除','',()=>go({confirmDel:true})));
    return h('div',{class:'detail'},
      bar('卡片详情',()=>go({view:'list',confirmDel:false})),
      h('div',{class:'scroll body'},
        fld('题目',c.q),fld('答案',c.a),
        fld('下次复习',dueOf(c)+'（'+dueLabel(dueOf(c),t)+'）'),
        fld('复习记录',rec),
        ui.confirmDel&&h('div',{class:'err'},'⚠ 删除后无法恢复，确认删除这张卡片？')),
      actions);
  }

  function formView(){
    const d=ui.draft||(ui.draft={q:'',a:''});
    const editing=!!d.id;
    const qi=h('textarea',{class:'inp',rows:'2',placeholder:'例如：光合作用的产物是什么？','aria-label':'问题',
      oninput:e=>{d.q=e.target.value;}});
    qi.value=d.q||'';
    const ai=h('textarea',{class:'inp',rows:'2',placeholder:'例如：葡萄糖和氧气','aria-label':'答案',
      oninput:e=>{d.a=e.target.value;}});
    ai.value=d.a||'';
    return h('div',{class:'form'},
      bar(editing?'编辑卡片':'新增卡片',closeForm),
      h('div',{class:'fbody'},
        h('label',null,'问题',qi),
        h('label',null,'答案',ai),
        ui.err&&h('div',{class:'err'},'⚠ '+ui.err),
        ui.msg&&h('div',{class:'ok'},'✓ '+ui.msg)),
      h('div',{class:'acts-row'},
        btn(editing?'保存修改':'保存','primary',()=>save(false),{disabled:!!ui.saving}),
        !editing&&btn('保存并继续','',()=>save(true),{disabled:!!ui.saving})));
  }

  const body=view==='form'?formView():view==='detail'?detailView():view==='list'?listView():studyView();
  const showNav=view==='study'||view==='list';
  root.append(h('div',{class:'fc','data-view':view},showNav&&nav(),body));
}

